function integer transform() {
    boolean patientCoverPresent = !isnull($in.1.patient_number);
    boolean procedureTariffPresent = !isnull($in.2.procedure_key);
    boolean payerSchemePresent = !isnull($in.3.payer_scheme);

    if (!patientCoverPresent || !procedureTariffPresent) {
        $out.0.invoice_reference = $in.0.charge_reference;
        $out.0.invoice_status = "REVIEW";
        $out.0.invoice_total_eur = 0D;
        $out.0.payer_amount_eur = 0D;
        $out.0.patient_amount_eur = 0D;
        $out.0.review_reason = !patientCoverPresent ? "PATIENT_COVER_NOT_FOUND" : "PROCEDURE_TARIFF_NOT_FOUND";
        return ALL;
    }

    if ($in.1.cover_status != "ELIGIBLE" || ($in.2.referral_needed && isnull($in.0.referral_reference))) {
        $out.0.invoice_reference = $in.0.charge_reference;
        $out.0.invoice_status = "REVIEW";
        $out.0.invoice_total_eur = 0D;
        $out.0.payer_amount_eur = 0D;
        $out.0.patient_amount_eur = 0D;
        $out.0.review_reason = "COVER_OR_REFERRAL_CHECK";
        return ALL;
    }

    boolean payerSchemeValid = payerSchemePresent
        && !isnull($in.0.treatment_date)
        && !isnull($in.3.valid_from)
        && $in.0.treatment_date >= $in.3.valid_from
        && (isnull($in.3.valid_until) || $in.0.treatment_date <= $in.3.valid_until);
    if (!payerSchemeValid) {
        $out.0.invoice_reference = $in.0.charge_reference;
        $out.0.invoice_status = "REVIEW";
        $out.0.invoice_total_eur = 0D;
        $out.0.payer_amount_eur = 0D;
        $out.0.patient_amount_eur = 0D;
        $out.0.review_reason = "PAYER_SCHEME_INVALID";
        return ALL;
    }

    decimal preVatAmount = $in.2.unit_fee_eur * $in.0.service_units + nvl($in.0.consumables_eur, 0D);
    decimal invoiceTotal = round(preVatAmount * (1D + $in.2.vat_percentage / 100D), 2);
    decimal payerAmount = round(invoiceTotal * $in.3.reimbursement_percentage / 100D, 2);

    $out.0.invoice_reference = $in.0.charge_reference;
    $out.0.invoice_status = "ISSUED";
    $out.0.invoice_total_eur = invoiceTotal;
    $out.0.payer_amount_eur = payerAmount;
    $out.0.patient_amount_eur = round(invoiceTotal - payerAmount, 2);
    $out.0.review_reason = null;
    return ALL;
}
