//#CTL2

function integer transform() {
    $out.0.filing_reference = $in.0.filing_reference;

    FoodRiskRule rule = null;
    string bestPrefix = "";

    FoodRiskRule candidate = lookup(SouthAsiaFoodRiskLookup).get($in.0.market_nation, bestPrefix);
    while (candidate != null) {
        if (length(candidate.municipality_prefix) > length(bestPrefix)
            && startsWith($in.0.municipal_code, candidate.municipality_prefix)
            && !isnull($in.0.audit_date)
            && $in.0.audit_date >= candidate.rule_start
            && (isnull(candidate.rule_end) || $in.0.audit_date <= candidate.rule_end)) {
            rule = candidate;
            bestPrefix = candidate.municipality_prefix;
        }
        candidate = lookup(SouthAsiaFoodRiskLookup).next();
