//#CTL2

function integer transform() {
    $out.0.member_number = $in.0.member_number;

    BeneluxLoyaltySchemeLookup_Record scheme =
        lookup(BeneluxLoyaltySchemeLookup).get($in.0.programme_market);

    if (isnull(scheme)) {
        $out.0.rewards_centre = "UNCONFIGURED";
        $out.0.earning_category = "MANUAL";
        $out.0.posting_day = extractDate($in.0.haulage_scan_time);
        $out.0.credited_points = 0L;
        $out.0.route_result = "MARKET_NOT_ENROLLED";
        $out.0.benefit_state = "ON_HOLD";
        $out.0.exception_note = "MARKET_NOT_ENROLLED";
        return ALL;
    }

    $out.0.rewards_centre = scheme.rewards_centre;
    $out.0.posting_day = extractDate($in.0.haulage_scan_time);

    string routeResult;
    if (isBlank($in.0.pickup_postcode) || isBlank($in.0.dropoff_postcode)) {
        routeResult = "ROUTE_DETAILS_MISSING";
    } else {
        boolean excluded = false;
        foreach (string prefix : scheme.excluded_destination_prefixes) {
            if (!isBlank(prefix)
                && startsWith($in.0.dropoff_postcode, prefix)) {
                excluded = true;
                break;
            }
        }
        routeResult = excluded ? "EXCLUDED_DESTINATION" : "ACCEPTED";
    }
    $out.0.route_result = routeResult;

    string earningCategory;
    if (routeResult != "ACCEPTED") {
        earningCategory = "INELIGIBLE";
    } else if ($in.0.booked_product == "PRIORITY"
               || (nvl($in.0.cross_border_move, false)
                   && $in.0.chargeable_tonnes <= 2D)) {
        earningCategory = "PRIORITY";
    } else {
        earningCategory = "REGULAR";
    }
    $out.0.earning_category = earningCategory;

    long creditedPoints;
    if (routeResult != "ACCEPTED") {
        creditedPoints = 0L;
    } else {
        decimal pointsRate = earningCategory == "PRIORITY"
            ? scheme.priority_points_per_eur : scheme.regular_points_per_eur;
        creditedPoints = decimal2long(
            floor($in.0.freight_charge_eur * pointsRate));
    }
    $out.0.credited_points = creditedPoints;

    string benefitState;
    if (routeResult != "ACCEPTED") {
        benefitState = "ON_HOLD";
    } else if (nvl($in.0.cross_border_move, false)
               && $in.0.freight_charge_eur > 1000D) {
        benefitState = "BONUS_REVIEW";
    } else {
        benefitState = "QUALIFIED";
    }
    $out.0.benefit_state = benefitState;

    string exceptionNote;
    switch (routeResult) {
        case "ROUTE_DETAILS_MISSING":
            exceptionNote = "ROUTE_DETAILS_MISSING";
            break;
        case "EXCLUDED_DESTINATION":
            exceptionNote = "EXCLUDED_DESTINATION";
            break;
        default:
            exceptionNote = null;
    }
    if (exceptionNote == null && benefitState == "BONUS_REVIEW") {
        exceptionNote = "HIGH_VALUE_CROSS_BORDER";
    }
    $out.0.exception_note = exceptionNote;

    return ALL;
}
