        $out.1.visit_reference = $in.0.visit_reference;
        $out.1.review_reason = "REWARD_SCHEME_UNAVAILABLE";
        $out.1.qualifying_spend = $in.0.qualifying_spend;
        return 1;
    }

    if (isnull($in.0.member_number) || isnull($in.0.workshop_date)) {
