//#CTL2
function integer transform() {
    $out.0.folio_reserva = $in.0.folio_reserva;

    if (isnull($in.0.servicio_juridico)) {
        $out.0.zona_legal = "PENDIENTE";
        $out.0.tasa_anticipo = 0D;
        $out.0.monto_anticipo = 0D;
        $out.0.estado_reserva = "REVISION_MANUAL";
        return ALL;
