            boolean inRange = !isnull(rec.vigente_desde) &&
                $in.0.fecha_reserva >= rec.vigente_desde &&
                (isnull(rec.vigente_hasta) || $in.0.fecha_reserva <= rec.vigente_hasta);

            if (prefixMatch && inRange &&
                (isnull(bestPrefijo) ||
                 length(rec.prefijo_sede) > length(bestPrefijo))) {
                bestPrefijo = rec.prefijo_sede;
                if (startsWith($in.0.canal_atencion, "VIDEO-") ||
                    contains($in.0.servicio_juridico, "MIGRATORIO")) {
                    selectedRate = rec.tasa_virtual;
                } else if (startsWith($in.0.servicio_juridico, "LABORAL-")) {
                    selectedRate = rec.tasa_laboral;
                } else {
                    selectedRate = rec.tasa_base;
                }
            }
            rec = lookup(AnticipoSedeLegalLookup).next();
        }
    }

    if (isnull(bestPrefijo)) {
        $out.0.zona_legal = "PENDIENTE";
        $out.0.tasa_anticipo = 0D;
        $out.0.monto_anticipo = 0D;
        $out.0.estado_reserva = "REVISION_MANUAL";
        return ALL;
    }

    $out.0.zona_legal = $in.0.pais_cliente + "-" + bestPrefijo;
    $out.0.tasa_anticipo = nvl(selectedRate, 0D);
    $out.0.monto_anticipo = round(
        $in.0.honorario_cotizado * $out.0.tasa_anticipo / 100D, 2);
    $out.0.estado_reserva = $out.0.tasa_anticipo == 0D ? "SIN_ANTICIPO" : "CONFIRMADA";
    return ALL;
}
