//#CTL2

function integer transform() {
    // Resolve lookup record
    OutletRosterLookup_Record lookupRec = lookup(OutletRosterLookup).get($in.0.outlet_code);

    integer baselinePoints;
    decimal weeklyLimit;
    boolean peakServiceDay;

    if (lookupRec != null) {
        baselinePoints   = lookupRec.baseline_staffing_points;
        weeklyLimit      = lookupRec.weekly_hours_limit;
        peakServiceDay   = lookupRec.peak_service_day;
    } else {
        baselinePoints   = 35;
        weeklyLimit      = 0D;
        peakServiceDay   = false;
    }

    // Compute staffing score
    integer score = baselinePoints;

    if ($in.0.uncovered_station_total >= 3) {
        score = score + 22;
    }
    if ($in.0.consecutive_roster_days >= 6) {
        score = score + 18;
    }
    if ($in.0.planned_week_hours > weeklyLimit) {
        score = score + 15;
    }
    if (!$in.0.has_food_safety_clearance) {
        score = score + 10;
    }
    if (startsWith($in.0.station_category, "GRILL_")) {
        score = score + 8;
    }

    if (score > 100) {
        score = 100;
    }

    // Derive assignment band
    string assignmentBand;
    if (score >= 85) {
        assignmentBand = "CRITICAL";
    } else if (score >= 60) {
        assignmentBand = "HIGH";
    } else if (score >= 30) {
        assignmentBand = "MODERATE";
    } else {
        assignmentBand = "LOW";
    }

    // Determine routing
    boolean scoreRoute = (score >= 70);
    boolean peakOrSevere = peakServiceDay || ($in.0.uncovered_station_total >= 5);
    boolean clearanceOrBadge = !$in.0.has_food_safety_clearance || isBlank($in.0.clockin_badge);
    boolean groupedRoute = peakOrSevere && clearanceOrBadge;
    boolean toException = scoreRoute || groupedRoute;

    date shiftDate = extractDate($in.0.shift_beginning);

    if (toException) {
        // Port 0: roster-exception queue
        $out.0.team_member_code = $in.0.team_member_code;
        $out.0.staffing_score   = score;
        $out.0.assignment_band  = assignmentBand;
        $out.0.shift_date       = shiftDate;

        // Exception reason by precedence
        string reason;
        if (!$in.0.has_food_safety_clearance) {
            reason = "MISSING_FOOD_SAFETY_CLEARANCE";
        } else if (peakServiceDay || ($in.0.uncovered_station_total >= 5)) {
            reason = "PEAK_SERVICE_COVERAGE";
        } else if ($in.0.planned_week_hours > weeklyLimit) {
            reason = "WEEKLY_HOURS_LIMIT";
        } else if ($in.0.consecutive_roster_days >= 6) {
            reason = "EXTENDED_ROSTER_RUN";
        } else if ($in.0.uncovered_station_total >= 3) {
            reason = "UNCOVERED_STATIONS";
        } else if (startsWith($in.0.station_category, "GRILL_")) {
            reason = "GRILL_STATION";
        } else {
            reason = "SCORE_GATE";
        }
        $out.0.exception_reason = reason;

        // Masked badge
        if (isBlank($in.0.clockin_badge)) {
            $out.0.masked_badge = "UNASSIGNED";
        } else {
            integer badgeLen = length($in.0.clockin_badge);
            integer suffixStart = (badgeLen > 4) ? (badgeLen - 4) : 0;
            $out.0.masked_badge = "****" + substring($in.0.clockin_badge, suffixStart, 4);
        }

        return 0;
    } else {
        // Port 1: published-roster audit
        $out.1.team_member_code = $in.0.team_member_code;
        $out.1.staffing_score   = score;
        $out.1.assignment_band  = assignmentBand;
