//#CTL2

function integer transform() {
    MarketOnboardingPolicyLookup_Record policy = lookup(MarketOnboardingPolicyLookup).get($in.0.market_iso);
    string settlementCurrency = "USD";
    decimal minimumMonthlyRevenue = 0D;
    integer followUpDays = 5;
    decimal maximumFacilityPct = 20D;
    string[] excludedTradePrefixes = [];

    if (!isnull(policy)) {
        settlementCurrency = nvl(policy.settlement_currency, "USD");
        minimumMonthlyRevenue = nvl(policy.minimum_monthly_revenue, 0D);
        followUpDays = nvl(policy.follow_up_days, 5);
        maximumFacilityPct = nvl(policy.maximum_facility_pct, 20D);
        excludedTradePrefixes = nvl(policy.excluded_trade_prefixes, []);
    }

    $out.0.onboarding_reference = $in.0.market_iso + "-" + $in.0.application_ref;
    $out.0.registered_name = upperCase(trim($in.0.enterprise_name));
    $out.0.settlement_currency = settlementCurrency;

    decimal facilityCeiling = $in.0.average_monthly_revenue * maximumFacilityPct / 100D;
    decimal approvedFacilityAmount = facilityCeiling;
    if (!isnull($in.0.requested_facility_amount) && $in.0.requested_facility_amount > 0L && $in.0.requested_facility_amount <= facilityCeiling) {
        approvedFacilityAmount = $in.0.requested_facility_amount;
    }
    $out.0.approved_facility_amount = round(approvedFacilityAmount, 2);

    string businessMaturity = "UNKNOWN";
    if (!isnull($in.0.incorporation_date)) {
        if (dateDiff(today(), $in.0.incorporation_date, day) < 365) {
            businessMaturity = "STARTUP";
        } else if ($in.0.outlet_count > 1L) {
            businessMaturity = "MULTI_OUTLET";
        } else {
            businessMaturity = "ESTABLISHED";
        }
    }
    $out.0.business_maturity = businessMaturity;

    string primaryPhone = null;
    string notificationEmail = null;
    if (!isBlank($in.0.contact_details_json)) {
        try {
            variant contactDetails = parseJson($in.0.contact_details_json);
            if (contactDetails typeof map) {
                variant phoneValue = contactDetails["primary_phone"];
                if (phoneValue typeof string) {
                    primaryPhone = cast(phoneValue, string);
                }
                variant emailValue = contactDetails["notification_email"];
                if (emailValue typeof string) {
                    notificationEmail = cast(emailValue, string);
                }
            }
        } catch (CTLException parseError) {
            primaryPhone = null;
            notificationEmail = null;
        }
    }
    $out.0.primary_phone = primaryPhone;
    $out.0.notification_email = notificationEmail;

    boolean contactable = (!isnull(primaryPhone) && !isBlank(primaryPhone)) || (!isnull(notificationEmail) && !isBlank(notificationEmail));
    boolean excludedTradeMatch = false;
    foreach (string excludedPrefix : excludedTradePrefixes) {
        if (!isnull(excludedPrefix) && !isBlank(excludedPrefix) && startsWith($in.0.trade_classification, excludedPrefix)) {
            excludedTradeMatch = true;
            break;
        }
    }
    boolean futureIncorporation = !isnull($in.0.incorporation_date) && $in.0.incorporation_date > today();
    string onboardingDecision;
    string decisionReason;

    if (excludedTradeMatch) {
        onboardingDecision = "REJECTED";
        decisionReason = "EXCLUDED_TRADE";
    } else if (futureIncorporation) {
        onboardingDecision = "REJECTED";
        decisionReason = "FUTURE_INCORPORATION_DATE";
    } else if (isnull($in.0.identity_verification_date) || !contactable) {
        onboardingDecision = "NEEDS_INFORMATION";
        decisionReason = "MISSING_CONTACT_OR_IDENTITY";
    } else if ($in.0.average_monthly_revenue < minimumMonthlyRevenue) {
        onboardingDecision = "MANUAL_REVIEW";
        decisionReason = "REVENUE_BELOW_MARKET_MINIMUM";
    } else {
        onboardingDecision = "APPROVED";
        decisionReason = null;
    }
    $out.0.onboarding_decision = onboardingDecision;
    $out.0.decision_reason = decisionReason;

    date nextActionDate = today();
    if (onboardingDecision == "NEEDS_INFORMATION") {
        nextActionDate = dateAdd(today(), 2L * followUpDays, day);
    } else if (onboardingDecision == "MANUAL_REVIEW") {
        nextActionDate = dateAdd(today(), followUpDays, day);
    }
    $out.0.next_action_date = nextActionDate;
    return ALL;
}
